public class Hiperbolas {
  public static void main(String[] args) {
      double[] arr = {Math.PI/2, Math.PI/3, Math.PI/4, Math.PI/5};
      double[] hiperes = new double[4];

      // La API Math de Java también incluye sinh, cosh, y tanh
      for(int i = 0; i < arr.length; i++) {
          hiperes[i] = Math.sinh(arr[i]);
      }

      System.out.println(java.util.Arrays.toString(hiperes));
  }
}
